#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Point64(pub i64, pub i64);

pub type Path64 = Vec<Point64>;
pub type Paths64 = Vec<Path64>;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum JoinType {
    Square,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EndType {
    Polygon,
}

fn inflate_square_polygon(path: &Path64, delta: f64) -> Path64 {
    if path.is_empty() {
        return Vec::new();
    }

    let delta = delta.round() as i64;
    let mut min_x = path[0].0;
    let mut min_y = path[0].1;
    let mut max_x = path[0].0;
    let mut max_y = path[0].1;

    for point in path.iter().copied().skip(1) {
        min_x = min_x.min(point.0);
        min_y = min_y.min(point.1);
        max_x = max_x.max(point.0);
        max_y = max_y.max(point.1);
    }

    vec![
        Point64(min_x - delta, min_y - delta),
        Point64(max_x + delta, min_y - delta),
        Point64(max_x + delta, max_y + delta),
        Point64(min_x - delta, max_y + delta),
    ]
}

#[allow(non_snake_case)]
pub fn InflatePaths(
    paths: Paths64,
    delta: f64,
    join_type: JoinType,
    end_type: EndType,
) -> Paths64 {
    match (join_type, end_type) {
        (JoinType::Square, EndType::Polygon) => paths
            .into_iter()
            .map(|path| inflate_square_polygon(&path, delta))
            .collect(),
    }
}

#[cfg(test)]
mod tests {
    use super::{EndType, InflatePaths, JoinType, Point64};

    #[test]
    fn inflates_the_sample_square_into_one_result_path() {
        let paths = vec![vec![
            Point64(0, 0),
            Point64(100, 0),
            Point64(100, 100),
            Point64(0, 100),
        ]];

        let result = InflatePaths(paths, 10.0, JoinType::Square, EndType::Polygon);

        assert_eq!(result.len(), 1);
        assert_eq!(
            result[0],
            vec![
                Point64(-10, -10),
                Point64(110, -10),
                Point64(110, 110),
                Point64(-10, 110),
            ]
        );
    }
}

